def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    opp_aggression = 0.0
    rich_aggressive = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                opp_aggression += float(bid)
                if float(bid) >= 85 and opp.get('budget', 0) >= 400:
                    rich_aggressive += 1

    alive_count = len(alive_opponents)
    if alive_count == 0:
        return min(budget, 18.0)

    avg_prev = opp_aggression / alive_count if alive_count > 0 else 0.0
    max_prev = max(prev_bids) if prev_bids else 0.0

    supply_ratio = (float(supply) - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_ratio < 0:
        supply_ratio = 0.0
    if supply_ratio > 1:
        supply_ratio = 1.0

    danger = 0.0
    if hp <= 2:
        danger += 1.0
    elif hp <= 4:
        danger += 0.6
    elif hp <= 6:
        danger += 0.3

    if no_water >= 2:
        danger += 1.0
    elif no_water >= 1:
        danger += 0.45

    tight_supply = supply <= 17
    loose_supply = supply >= 22

    if tight_supply:
        danger += 0.45
    elif loose_supply:
        danger -= 0.2

    if day >= 8:
        danger += 0.15

    if danger < 0:
        danger = 0.0

    if budget <= 0:
        return 0.0

    if danger >= 1.6:
        target = max(92.0, max_prev + 2.5, avg_prev + 4.0)
    elif danger >= 1.0:
        target = max(74.0, avg_prev + 1.5)
        if tight_supply:
            target = max(target, max_prev + 1.0)
    elif danger >= 0.5:
        if loose_supply and rich_aggressive >= 1:
            target = 24.0
        else:
            target = max(38.0, min(68.0, avg_prev * 0.72))
    else:
        if loose_supply:
            target = 12.0
        elif max_prev >= 90:
            target = 20.0
        else:
            target = 28.0

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = 70.0 * (8 - day) * 0.18
    max_affordable = max(0.0, budget - reserve_floor)
    if max_affordable <= 0:
        max_affordable = min(budget, 25.0)

    bid = min(target, budget, max_affordable)

    if hp <= 2 or no_water >= 2:
        bid = min(budget, max(bid, 96.0))
    elif hp <= 4 and tight_supply:
        bid = min(budget, max(bid, 82.0))

    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive.append((opp_id, opp))

    if not alive:
        return min(budget, DAILY_SALARY * 0.4)

    # Read yesterday bids from immediate previous_trace only.
    prev_bids = []
    for opp_id, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass

    # Estimate opponent aggressiveness.
    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    # Base target bid: aim to win when supply is tight or my HP is critical.
    # Supply is between 15 and 25; higher supply means less need to outbid.
    supply_ratio = (supply - float(MIN_SUPPLY)) / float(MAX_SUPPLY - MIN_SUPPLY)  # 0..1
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # If I'm in danger, bid harder.
    if hp <= 2 or no_water_days >= 2:
        urgency = 1.0
    elif hp <= 4 or no_water_days >= 1:
        urgency = 0.65
    else:
        urgency = 0.35

    # If opponents were bidding high yesterday, raise slightly to avoid losing.
    # Cindy survived; others died; high highest_prev likely means some were aggressive.
    pressure = 0.0
    if highest_prev >= DAILY_SALARY * 0.85:
        pressure = 0.35
    elif highest_prev >= DAILY_SALARY * 0.6:
        pressure = 0.2
    elif highest_prev > 0:
        pressure = 0.1

    # Compute desired bid.
    # Keep it below full daily salary to preserve budget; escalate with urgency and pressure.
    target = DAILY_SALARY * (0.45 + urgency * 0.35 - supply_ratio * 0.15 + pressure)

    # If Cindy was the only one alive, she likely bids consistently; match her band.
    # Use avg_prev as a soft cap.
    if avg_prev > 0:
        target = min(target, avg_prev * 1.05)

    # Ensure we can pay.
    bid = min(budget, max(1.0, target))

    # If supply is very low (near 15), slightly increase bid to secure water.
    if supply <= float(MIN_SUPPLY) + 0.5:
        bid = min(budget, bid * 1.15)

    return float(bid)

